styles.tutorial:
section[data-skill-hub] .-w {
  display: grid;
  grid-template-columns: repeat(14, 1fr);
  grid-template-rows: 1fr auto auto auto auto 1fr;
  align-items: center;
  /* column-gap: var(--g-gap); */
  min-height: calc(var(--vh, 1vh) * 100);
}

section[data-skill-hub] .-w .cross {
  display: none;
}
@media (min-width: 1024px) {
  section[data-skill-hub] .-w {
    grid-template-rows: 2fr 1fr auto auto 1fr 2fr;
  }
  section[data-skill-hub] .-w .cross {
    grid-column-start: 3;
    grid-column-end: 13;
    grid-row-start: 2;
    grid-row-end: 6;
    justify-self: stretch;
    align-self: stretch;
    display: block;
    background-image: linear-gradient(
        to right,
        transparent 50%,
        rgba(var(--c-grey-dark-rgb), 0.4) calc(50% + 1px),
        transparent calc(50% + 1px)
      ),
      linear-gradient(to top, transparent 50%, rgba(var(--c-grey-dark-rgb), 0.4) calc(50% + 1px), transparent calc(50% + 1px));
    background-repeat: no-repeat;
  }
}

section[data-skill-hub] .item {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: var(--g-gap);
  padding: var(--g-gap) 0;
  cursor: default;
  position: relative;
}
section[data-skill-hub] .item figure {
  flex-shrink: 0;
  width: var(--h3);
  border-radius: var(--g-gap);
  overflow: hidden;
}
section[data-skill-hub] .-l,
section[data-skill-hub] .-r {
  grid-column-start: 1;
  grid-column-end: 15;
}

@media (min-width: 1024px) {
  section[data-skill-hub] .-l {
    grid-column-start: 3;
    grid-column-end: 8;
  }
  section[data-skill-hub] .-r {
    grid-column-start: 8;
    grid-column-end: 13;
  }
  section[data-skill-hub] .water,
  section[data-skill-hub] .earth {
    grid-row-start: 3;
    grid-row-end: 4;
  }
  section[data-skill-hub] .air,
  section[data-skill-hub] .fire {
    grid-row-start: 4;
    grid-row-end: 5;
  }

  section[data-skill-hub] .item {
    padding: var(--p) calc(var(--g-gap) / 2);
  }
  section[data-skill-hub] .item::before {
    content: '';
    position: absolute;
    inset: calc(var(--g-gap) / 2);

    background-color: rgba(var(--c-grey-dark-rgb), 0.2);
    border-radius: var(--g-gap);

    opacity: 0;
    scale: 0.5;
    transition:
      opacity 0.3s var(--easing-function),
      scale 0.3s var(--easing-function);
  }
  section[data-skill-hub] .item:hover::before {
    opacity: 1;
    scale: 1;
    transition:
      opacity 0.6s var(--easing-function-2),
      scale 0.6s var(--easing-function-2);
  }
  section[data-skill-hub] .item figure {
    opacity: 1;
    scale: 1;
    transition:
      opacity 0.6s var(--easing-function-2),
      scale 0.6s var(--easing-function-2);
  }
  section[data-skill-hub] .-w:has(.item:hover) .item figure {
    scale: 0.5;
  }
  section[data-skill-hub] .-w .item:hover figure {
    scale: 0.25 !important;
    opacity: 0;
    transition:
      opacity 0.3s var(--easing-function),
      scale 0.3s var(--easing-function);
  }
  section[data-skill-hub] .-w:has(.item:hover) .item span {
    color: var(--c-grey-dark);
  }
  section[data-skill-hub] .item:hover span {
    color: var(--c-white) !important;
  }
}

section[data-skill-hub] .tutorial-cursor,
section[data-skill-hub] .tutorial-cursor-echo {
  display: none;
}
@media (min-width: 1024px) {
  section[data-skill-hub] .tutorial-cursor-echo {
    position: fixed;
    z-index: 100;
    left: 0;
    top: 0;
    display: block;
    width: var(--g-gap);
    height: var(--g-gap);
    border-radius: 50%;
    background-color: var(--c-grey-dark);
    transform: translate3d(calc(var(--x) * 1px + 0.5rem), calc(var(--y) * 1px + 0.75rem), 0);
    will-change: transform;
  }
  section[data-skill-hub] .tutorial-cursor {
    display: grid;
    place-items: center;

    position: fixed;
    z-index: 100;
    left: 0;
    top: 0;
    pointer-events: none;
    margin-left: 1rem;
    margin-top: 1.5rem;
    transform: translate3d(calc(var(--x) * 1px + 1rem), calc(var(--y) * 1px + 1.5rem), 0) rotate(calc(var(--x-lerp) * 0.5deg));
    will-change: transform;
  }
  section[data-skill-hub] .tutorial-cursor figure {
    grid-area: 1 / 1;
    border-radius: var(--g-gap);
    overflow: hidden;
    width: 12rem;
    opacity: 0;
    scale: 0.5;
    translate: 0 25%;
    transition:
      opacity 0.3s var(--easing-function),
      scale 0.3s var(--easing-function),
      translate 0.3s var(--easing-function);
    will-change: opacity, scale, translate;
  }
  section[data-skill-hub] .tutorial-cursor.-target-1 .image-1,
  section[data-skill-hub] .tutorial-cursor.-target-2 .image-2,
  section[data-skill-hub] .tutorial-cursor.-target-3 .image-3,
  section[data-skill-hub] .tutorial-cursor.-target-4 .image-4 {
    z-index: 101;
    opacity: 1;
    scale: 1;
    translate: 0 0;
    transition:
      opacity 0s var(--easing-function-2),
      scale 0.6s var(--easing-function-2),
      translate 0.6s var(--easing-function-2);
  }
}

section[data-skill-hub] .-w .note {
  grid-column-start: 1;
  grid-column-end: 15;
  grid-row-start: 1;
  justify-self: center;
  align-self: start;
  text-align: center;
  z-index: 40;
  margin-top: var(--h0);
  background-color: var(--c-black);
}
